return items.map(item => {
  try {
    // 1. Gemini'nin ürettiği ham metni al (Senin veri yapına göre yol)
    // Veri yapısı bazen değişebileceği için güvenli erişim (?.) kullanıyoruz
    const rawText = item.json.content?.parts?.[0]?.text || item.json.text;

    if (!rawText) {
      throw new Error("Metin verisi bulunamadı");
    }

    // 2. Markdown temizliği: ```json, ``` ve boşlukları sil
    // Regex kullanımı: Her türlü markdown işaretini temizler
    const cleanText = rawText.replace(/```json/g, "").replace(/```/g, "").trim();

    // 3. String'i gerçek JSON objesine çevir
    const parsedData = JSON.parse(cleanText);

    // 4. Temiz veriyi n8n formatında geri döndür
    return { json: parsedData };

  } catch (error) {
    // Hata durumunda akışı bozma, hata mesajı döndür
    return {
      json: {
        error: "JSON ayrıştırma hatası",
        message: error.message,
        input: item.json // Hatalı gelen veriyi kontrol edebilmen için
      }
    };
  }
});

const baseFormula = $('Edit Fields1').first().json.Formul;

// Search node'dan gelen tüm dosyalar
const items = $input.all();

function escapeRegex(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Sadece şu formata uyanları kabul et:
// baseFormula.1
// baseFormula.2
// baseFormula.15
const regex = new RegExp(`^${escapeRegex(baseFormula)}\\.(\\d+)$`);

let maxVersion = 0;

for (const item of items) {
  const fileName =
    item.json.name ||
    item.json.title ||
    item.json.fileName ||
    '';

  const match = fileName.match(regex);

  if (match) {
    const version = Number(match[1]);

    if (!Number.isNaN(version) && version > maxVersion) {
      maxVersion = version;
    }
  }
}

const nextVersion = maxVersion + 1;
const finalFileName = `${baseFormula}.${nextVersion}`;

return [
  {
    json: {
      baseFormula,
      numara: nextVersion,
      finalFileName,
      anaIsKolu: $('Edit Fields1').first().json.anaIsKolu
    },
  },
];

