const raw = items[0].json.content[0].text;

let clean = raw.replace(/```json\s*/gi, '').replace(/```/g, '').trim();

const first = clean.indexOf('{');
const last = clean.lastIndexOf('}');
if (first !== -1 && last !== -1) {
  clean = clean.substring(first, last + 1);
}

let parsed;
try {
  parsed = JSON.parse(clean);
} catch (err) {
  throw new Error("İptal parse hatası: " + err.message + "\nHam çıktı:\n" + clean);
}

// iptal alanını gerçek boolean'a çevir
if (typeof parsed.iptal === 'string') {
  parsed.iptal = parsed.iptal.toLowerCase() === 'true';
}

// fatura_no_parcasi eksikse boş string yap
parsed.fatura_no_parcasi = parsed.fatura_no_parcasi ?? "";

return [{ json: parsed }];

